class Solution {
    public int minDeletions(String text){
        int[] frequency=new int[26];
        for(char letter:text.toCharArray())frequency[letter-'a']++;
        Set<Integer> used=new HashSet<>();
        int deletions=0;
        for(int count:frequency){
            while(count>0&&used.contains(count)){
                count--;
                deletions++;
            }
            if(count>0)used.add(count);
        }
        return deletions;
    }
}

code.kotlin:
class Solution {
    fun minDeletions(text:String):Int{
        val frequency=IntArray(26);
        for(letter in text)frequency[letter-'a']++;
        val used=mutableSetOf<Int>();
        var deletions=0;
        for(original in frequency){
            var count=original;
            while(count>0&&count in used){
                count--;
                deletions++
            };
            if(count>0)used.add(count)
        };
        return deletions
    }
}

code.cpp:
class Solution {
    public: int minDeletions(string text){
        vector<int> frequency(26);
        for(char letter:text)++frequency[letter-'a'];
        unordered_set<int> used;
        int deletions=0;
        for(int count:frequency){
            while(count>0&&used.count(count)){
                --count;
                ++deletions;
            }
            if(count)used.insert(count);
        }
        return deletions;
    }
};
